def solve(rows):
    state = 9
    kept_rows = []
    original_index = 0
    for row in rows:
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and '|' in row:
            try:
                weight = int(row.split('|')[1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            total_int_sum = 0
            string_length_sum = 0
            for item in row:
                if isinstance(item, int) and not isinstance(item, bool):
                    total_int_sum += item
                elif isinstance(item, str):
                    string_length_sum += len(item)
            weight = total_int_sum + string_length_sum

        if (state + weight + original_index) % 11 != 5 or original_index == len(rows) - 1:
            kept_rows.append(row)
            state = (5 * state + weight) % 11
            if weight == 0: 
                state = 9
        else:
            state = 9
        original_index += 1

    if not kept_rows:
        return 0

    kept_length = len(kept_rows)
    if kept_length > 0:
        rotated_rows = kept_rows[1:] + [kept_rows[0]]
    else:
        rotated_rows = []

    total_price = 0
    for row in rotated_rows:
        if isinstance(row, list) and len(row) == 2 and isinstance(row[0], int) and isinstance(row[1], int):
            price = row[0]
            discount = row[1]
            discount_amount = min(discount, 8)
            discounted_price = price - discount_amount
            total_price += max(0, int(round(discounted_price)))

    return total_price

